package dev.eugheist.ttmodern;
final class BedrockGenerationAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT bedrock generation: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){
  var level=server.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","bedrock")));check(level!=null&&level.getChunkSource().getGenerator() instanceof BedrockChunkGenerator,"actual dimension/provider loaded");check(level.getMinBuildHeight()==0&&level.getMaxBuildHeight()==256,"original 256 block world height");
  var entries=BedrockOres.entries(java.util.Set.of("oreFirestone"));check(entries.size()>=15,"vanilla and Thaumcraft ore tags resolved: "+entries.size());for(var ore:java.util.List.of(BedrockOres.AIR,BedrockOres.EARTH,BedrockOres.ENTROPY,BedrockOres.FIRE,BedrockOres.ORDER,BedrockOres.WATER))check(entries.stream().anyMatch(e->e.kind()==ore),"original infused ore "+ore);check(BedrockOres.entries(java.util.Set.of("oreCoal","oreIron")).stream().noneMatch(e->e.kind()==BedrockOres.COAL||e.kind()==BedrockOres.IRON),"original blacklist names");
  var weighted=java.util.List.of(new BedrockOres.Entry(BedrockOres.COAL,net.minecraft.world.level.block.Blocks.COAL_ORE),new BedrockOres.Entry(BedrockOres.DIAMOND,net.minecraft.world.level.block.Blocks.DIAMOND_ORE));for(int boundary:new int[]{0,2647,2648,2714}){var random=new java.util.Random(){@Override public int nextInt(int bound){check(bound==2715,"original exact weight sum");return boundary;}};check(BedrockOres.choose(random,weighted)==(boundary<2648?net.minecraft.world.level.block.Blocks.COAL_ORE:net.minecraft.world.level.block.Blocks.DIAMOND_ORE),"exact weighted boundary "+boundary);}
  check(BedrockOres.choose(new java.util.Random(),java.util.List.of())==net.minecraft.world.level.block.Blocks.GOLD_ORE,"empty optional catalog safe gold fallback");
  var chunk=level.getChunk(10,10);var allowed=entries.stream().map(e->e.block()).collect(java.util.stream.Collectors.toSet());int ores=0;
  for(int x=0;x<16;x++)for(int z=0;z<16;z++)for(int y=0;y<256;y++){var state=chunk.getBlockState(new net.minecraft.core.BlockPos(160+x,y,160+z));if(!state.is(net.minecraft.world.level.block.Blocks.BEDROCK)){check(allowed.contains(state.getBlock()),"only original catalog ores in solid bedrock");ores++;}if(y==0||y>=254)check(state.is(net.minecraft.world.level.block.Blocks.BEDROCK),"intact bottom/portal roof");}check(ores>0,"actual populated vertical ore cluster in native chunk");check(level.getBiome(new net.minecraft.core.BlockPos(160,100,160)).is(net.minecraft.world.level.biome.Biomes.BEACH),"original beach biome (MCP field_76787_r)");
  var test=server.overworld();var saved=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();for(int x=-18;x<=-4;x++)for(int y=65;y<=80;y++)for(int z=27;z<=41;z++){var pos=new net.minecraft.core.BlockPos(x,y,z);saved.put(pos,test.getBlockState(pos));}
  int[] sizes={0,1,5,19},counts={0,0,4,24};String[] hashes={"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","aa7965066bac9ef768cebffde394700a826aa251ee61e620f3aeabe084f5916a","e391775cfe4f5942338c336554ab87d4547e609d67e74b50b6b66825ca344864"};long[] rng={7527149614318158917L,4903670709408325571L,7887132294115108461L,4568928085426670717L};
  try{for(int i=0;i<sizes.length;i++){saved.keySet().forEach(pos->test.setBlock(pos,net.minecraft.world.level.block.Blocks.BEDROCK.defaultBlockState(),2));var random=new java.util.Random(164);BedrockVeins.generate(test,random,-19,73,26,sizes[i],net.minecraft.world.level.block.Blocks.GOLD_ORE.defaultBlockState());var actual=new java.util.TreeSet<String>();for(var pos:saved.keySet())if(test.getBlockState(pos).is(net.minecraft.world.level.block.Blocks.GOLD_ORE))actual.add(pos.getX()+","+pos.getY()+","+pos.getZ());String digest=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(String.join(";",actual).getBytes(java.nio.charset.StandardCharsets.UTF_8)));check(actual.size()==counts[i]&&digest.equals(hashes[i])&&random.nextLong()==rng[i],"independent original MC1.7.10 class ase footprint/RNG size "+sizes[i]+" got "+actual.size()+" "+digest);}}
  catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}finally{saved.forEach((pos,state)->test.setBlock(pos,state,2));}
  System.out.println("TT BEDROCK GENERATION AUDIT: ALL PASS (actual dimension/height/beach/solid chunks/ore clusters,original weights/blacklist/six infused ores,independent MC1.7.10 vein footprints and RNG)");
 }
}
